def _format_srd_sections(sections: list[str]) -> str:
    """Собрать список секций SRD в компактный текст (общий хелпер)."""
    return "\n".join(s.strip() for s in sections)


def format_srd_for_prompt() -> str:
    """Собрать все правила в компактный текст для system prompt.

    v3.0.0.22: убраны SPECIES, FEATS_TEXT, BACKGROUNDS_TEXT, EQUIPMENT_QUICK —
    модель их знает без референса; экономия ~7-8K токенов на ход.
    Механика и классы — оставлены (критично для СЛ, кубиков, прогрессии).
    """
    return _format_srd_sections([
        CORE_MECHANICS,
        ABILITIES_AND_SKILLS,
        COMBAT_RULES,
        CONDITIONS,
        MULTIPLAYER_MECHANICS,
        NPC_COMPANIONS,
        RESTING,
        ENCOUNTER_DESIGN,
        SPELLCASTING,
        CLASSES,
    ])


def format_srd_lite_for_prompt() -> str:
    """Облегчённые SRD правила для повторных сообщений.

    Только базовые механики (CORE + ABILITIES + COMBAT + CONDITIONS + RESTING).
    Без классов, мультиплеера, NPC, энкаунтеров, спелл-кастинга —
    модель уже знает их из первого сообщения и истории диалога.

    Экономия: ~13K chars (~53% SRD).
    """
    return _format_srd_sections([
        CORE_MECHANICS,
        ABILITIES_AND_SKILLS,
        COMBAT_RULES,
        CONDITIONS,
        RESTING,
    ])


def _extract_spell_dice(spell_name: str) -> str:
    """Извлечь кубики урона/лечения из SRD описания заклинания."""
    import re
    srd = ALL_SPELLS_FLAT.get(spell_name)
    if not srd:
        return ""
    desc = srd.get("desc", "")
    dice_pattern = re.findall(r'(\d+d\d+(?:\s*\+\s*\d+)?)', desc)
    if not dice_pattern:
        return ""
    # Сортируем по величине (NdM → N×M), самый большой вперёд
    def _dice_size(d):
        m = re.match(r'(\d+)d(\d+)', d.replace(' ', ''))
        return int(m.group(1)) * int(m.group(2)) if m else 0
    dice_pattern.sort(key=_dice_size, reverse=True)
    return dice_pattern[0].replace(' ', '')


def format_character_for_prompt(character: dict) -> str:
    """Форматировать информацию о персонаже для system prompt."""
    import json

    stats = character.get('stats', {})
    if isinstance(stats, str):
        stats = json.loads(stats)
    str_val = stats.get('str', 10)
    dex_val = stats.get('dex', 10)
    con_val = stats.get('con', 10)
    int_val = stats.get('int', 10)
    wis_val = stats.get('wis', 10)
    cha_val = stats.get('cha', 10)

    # Модификаторы
    def mod(v): return (v - 10) // 2
    def mod_str(v): return f"+{mod(v)}" if mod(v) >= 0 else str(mod(v))

    level = character.get('level', 1)
    prof_bonus = next((pb for lvl, pb in sorted(DND_SRD['proficiency_by_level'].items(), reverse=True) if level >= lvl), 2)

    # Владения спасбросками из CLASS_PROFICIENCIES
    class_name = character.get('class_name', '')
    profs = CLASS_PROFICIENCIES.get(class_name, {})
    saves = profs.get('saves', [])

    # Навыки
    skill_profs = character.get('skill_proficiencies', [])
    if isinstance(skill_profs, str):
        skill_profs = json.loads(skill_profs)

    equipped_str = _format_inventory_for_prompt(character.get('items', []))
    features_str = _format_features_for_prompt(character.get('features', []))
    spells_str = _format_spells_for_prompt(character.get('spells', []) or character.get('character_spells', []))

    # Предыстория (первые 100 символов)
    backstory = character.get('backstory', '')
    backstory_short = (backstory[:120] + "...") if len(backstory) > 120 else backstory

    # Внешность персонажа (если уже определена)
    appearance = character.get('appearance', '')
    appearance_str = f"\n- **Внешность**: {appearance}" if appearance else ""

    karma_str = _format_karma_for_prompt(character.get('karma', 0))

    return f"""
## Текущий персонаж игрока
- **Имя**: {character.get('name', 'Неизвестно')}
- **Раса**: {character.get('race', 'Неизвестно')}, **Класс**: {class_name}, уровень {level} (бонус умения +{prof_bonus}){appearance_str}
- **Характеристики**:
  - СИЛ {str_val} ({mod_str(str_val)}) | ЛОВ {dex_val} ({mod_str(dex_val)}) | ТЕЛ {con_val} ({mod_str(con_val)})
  - ИНТ {int_val} ({mod_str(int_val)}) | МУД {wis_val} ({mod_str(wis_val)}) | ХАР {cha_val} ({mod_str(cha_val)})
- **HP**: {character.get('hp_current', 0)}/{character.get('hp_max', 0)}, **КД**: {character.get('ac', 10)}, **Скорость**: {character.get('speed', 30)} фт.
- **Золото**: {character.get('gold', 0)} ЗМ{karma_str}
- **Спасброски**: {', '.join(s.upper() for s in saves) if saves else '—'} (+{prof_bonus})
- **Владения навыками**: {', '.join(s.replace('_', ' ').title() for s in skill_profs) if skill_profs else '—'}{equipped_str}{features_str}
- **Языки**: {', '.join(character.get('languages', ['общий'])) if isinstance(character.get('languages'), list) else character.get('languages', 'общий')}{spells_str}
- **Предыстория**: {backstory_short or 'не указана'}

**ВАЖНО**: При любых проверках характеристик, спасбросках, атаках и определении КД используй ТОЛЬКО эти значения.
Модификатор для проверки = модификатор характеристики (в скобках выше) + бонус умения (+{prof_bonus}), если персонаж владеет навыком/спасброском.
Игрок может кидать кубики; прибавляй к его результату правильный модификатор.
"""


def _format_inventory_for_prompt(items) -> str:
    """Предметы — показываем ВЕСЬ инвентарь (экипированное + рюкзак),
    чтобы мастер учитывал предметы и не выдавал дубли."""
    if not items:
        return ""
    equipped = []
    carried = []
    for it in items:
        name = it.get('item_name', it.get('item_key', '?'))
        slot = it.get('slot', '?')
        if it.get('equipped'):
            equipped.append(f"{name} ({slot})")
        else:
            qty = it.get('qty', 1)
            if qty and qty > 1:
                name = f"{name} ×{qty}"
            carried.append(name)
    parts = []
    if equipped:
        parts.append("**Экипировано**: " + ", ".join(equipped))
    if carried:
        parts.append("**В рюкзаке**: " + ", ".join(carried))
    return "\n- " + "\n- ".join(parts) if parts else ""


def _format_features_for_prompt(features) -> str:
    """Черты персонажа (первые 8)."""
    if isinstance(features, str):
        import json
        features = json.loads(features)
    if not features:
        return ""
    feat_names = [f.get('name', '?') for f in features[:8]]
    return "\n- **Умения**: " + ", ".join(feat_names)


def _format_spells_for_prompt(spells) -> str:
    """Заклинания: заговоры и leveled."""
    if not spells:
        return ""
    cantrips = [s for s in spells if s.get('spell_level', s.get('level', 99)) == 0]
    leveled = [s for s in spells if s.get('spell_level', s.get('level', 99)) > 0]
    parts = []
    if cantrips:
        c_names = []
        for s in cantrips[:8]:
            name = s.get('spell_name', s.get('name', '?'))
            dice = _extract_spell_dice(name)
            c_names.append(f"{name} ({dice})" if dice else name)
        parts.append("Заговоры: " + ", ".join(c_names))
    if leveled:
        l_names = []
        for s in leveled[:12]:
            name = s.get('spell_name', s.get('name', '?'))
            lvl = s.get('spell_level', s.get('level', '?'))
            dice = _extract_spell_dice(name)
            display = f"{name} ({lvl} ур."
            if dice:
                display += f", {dice}"
            display += ")"
            l_names.append(display)
        parts.append("Заклинания: " + ", ".join(l_names))
    return "\n- **" + " | ".join(parts) if parts else ""


def _format_karma_for_prompt(karma: int) -> str:
    """Карма с человеческой меткой."""
    if not karma:
        return ""
    karma_label = "😇 Герой" if karma >= 50 else ("😊 Добряк" if karma >= 20 else ("😐 Нейтрал" if karma > -20 else ("😈 Злодей" if karma <= -50 else "🙁 Негодяй")))
    return f"\n- **Карма**: {karma} ({karma_label})"


