MIXED_LANGUAGE_THRESHOLD = 25

# ============================================================
#  ОП & MILESTONES (D&D 5e)
# ============================================================
# ОП thresholds to reach each level
XP_THRESHOLDS = {
    1: 0,       # starting
    2: 300,
    3: 900,
    4: 2700,
    5: 6500,
    6: 14000,
    7: 23000,
    8: 34000,
    9: 48000,
    10: 64000,
    11: 85000,
    12: 100000,
    13: 120000,
    14: 140000,
    15: 165000,
    16: 195000,
    17: 225000,
    18: 265000,
    19: 305000,
    20: 355000,
}

# Suggested ОП awards for DM reference (DM tracks internally, NEVER shows numbers to player)
# XP is for OVERCOMING CHALLENGES — moral alignment doesn't matter.
# A villain gets XP for burning a village just like a hero gets XP for saving it.
MILESTONE_XP = {
    # Heroic / neutral deeds
    "minor_quest": 200,        # side quest, minor discovery
    "major_quest": 800,        # main quest milestone
    "boss_defeat": 1200,       # defeating a major enemy
    "puzzle_solved": 150,      # clever puzzle solution
    "roleplay_excellent": 100,  # exceptional roleplay moment
    "exploration": 50,         # discovering a hidden area
    "heroic_act": 300,         # selfless or heroic deed
    "clever_solution": 200,    # creative problem-solving
    # Villainous / dark deeds
    "massacre": 400,           # slaughtering a village / community
    "robbery": 300,            # robbing a caravan, bank, or noble
    "assassination": 500,      # killing an important figure
    "deal_with_dark_power": 600,  # pact with demon, devil, or dark entity
    "betrayal": 400,           # betraying allies or someone who trusted you
    "terror_reign": 800,       # establishing a reign of terror in a region
    "corruption": 300,         # corrupting an innocent, spreading evil influence
    # Seduction / social manipulation
    "seduction_success": 200,  # successfully seducing an important NPC
    "seduction_critical": 400, # seducing a major figure (noble, villain, quest giver)
    "honey_pot": 500,          # using intimacy to extract secrets, access, or favors
    "orgy_or_group": 350,      # memorable group encounter with plot significance
}

# Milestone check threshold: DM checks if ОП ≥ next level threshold
def xp_for_next_level(current_level: int) -> int:
    """How much ОП to reach the next level from current."""
    return XP_THRESHOLDS.get(current_level + 1, 999999)

def check_level_up(current_level: int, total_xp: int) -> bool:
    """Check if character should level up based on ОП."""
    return total_xp >= xp_for_next_level(current_level)


# ============================================================
# АВТОГЕНЕРАЦИЯ: мировые классы → мультикласс + hit-die
# ============================================================
# Мировые классы (ключ "<Имя>__<world>", например "Солдат__nuclear_wasteland")
# не имели записей в MULTICLASS_REQUIREMENTS / MULTICLASS_PROFICIENCIES /
# CLASS_HIT_DIE → мультикласс был невозможен, hit_die падал в дефолт 8.
# Здесь — автогенерация по классификатору world_class_rules.py:
#   - если у класса есть ручная plain-запись (базовые D&D классы) — копия её данных;
#   - иначе — правила из классификатора (stat-требование 13, profs по типу, hit_die 6/8/10/12).
# Суффиксированные ключи добавляются ВСЕГДА (never clobber существующие) —
# это фиксирует 14 классов, у которых plain-имя есть в CLASS_HIT_DIE, а
# суффиксированного нет (levelup._resolve_target_class ищет точный суффикс-ключ).


def _generate_world_class_multiclass_data() -> None:
    from app.knowledge.worlds import WORLD_CLASSES
    from app.knowledge.world_class_rules import get_world_class_rules

    for _world_key, _classes in WORLD_CLASSES.items():
        for _class_name in _classes:
            _sfx = f"{_class_name}__{_world_key}"
            _rules = get_world_class_rules(_sfx)
            if _sfx not in MULTICLASS_REQUIREMENTS:
                # значение может быть dict (AND) или list[dict] (OR) — ссылка на константу
                MULTICLASS_REQUIREMENTS[_sfx] = (
                    MULTICLASS_REQUIREMENTS[_class_name]
                    if _class_name in MULTICLASS_REQUIREMENTS
                    else _rules["requirement"]
                )
            if _sfx not in MULTICLASS_PROFICIENCIES:
                MULTICLASS_PROFICIENCIES[_sfx] = (
                    dict(MULTICLASS_PROFICIENCIES[_class_name])
                    if _class_name in MULTICLASS_PROFICIENCIES
                    else dict(_rules["proficiencies"])
                )
            if _sfx not in CLASS_HIT_DIE:
                CLASS_HIT_DIE[_sfx] = (
                    CLASS_HIT_DIE[_class_name]
                    if _class_name in CLASS_HIT_DIE
                    else _rules["hit_die"]
                )


_generate_world_class_multiclass_data()

